import React from "react";

// PortugalNumeroDeIdentificacaoFiscalView component
//
// A headless display component for showing Portugal's
// Número de Identificação Fiscal (NIF) in a read-only format.
//
// Props:
//   className — string, optional. CSS class name.
//   label — string, required. Accessible label for screen readers via aria-label.
//   value — string, default "". The identifier string to display.
//   ...restProps — additional HTML attributes spread onto the <span>.
//
// Syntax:
//   <PortugalNumeroDeIdentificacaoFiscalView label="Tax Identification Number" value={value} />
//
// Accessibility:
//   - aria-label provides the accessible name so screen readers announce the purpose
//
// References:
//   - https://en.wikipedia.org/wiki/Personal_identification_number_(Portugal)

export interface PortugalNumeroDeIdentificacaoFiscalViewProps {
    className?: string;
    /** Accessible label for screen readers */
    label: string;
    /** The identifier to display */
    value?: string;
    [key: string]: unknown;
}

export default function PortugalNumeroDeIdentificacaoFiscalView({
    className = "",
    label,
    value = "",
    ...restProps
}: PortugalNumeroDeIdentificacaoFiscalViewProps) {
    return (
        <span
            className={`portugal-numero-de-identificacao-fiscal-view ${className}`}
            aria-label={label}
            {...restProps}
        >
            {value}
        </span>
    );
}
